<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import api from '@/api'
import { useAuthStore } from '@/stores/auth'
import { currency, dateTime, statusMap } from '@/utils/format'

const auth = useAuthStore()
const active = ref('products')
const products = ref([])
const notifications = ref([])
const editing = ref(false)
const profile = reactive({ nickname:'',phone:'',campus:'',student_no:'',bio:'',avatar:'' })
const productStats = computed(() => ({ total:products.value.length, published:products.value.filter(i=>i.status==='published').length, pending:products.value.filter(i=>i.status==='pending').length, sold:products.value.filter(i=>i.status==='sold').length }))
const load = async () => { products.value=await api.get('/my/products'); notifications.value=await api.get('/notifications'); Object.assign(profile,auth.user) }
const saveProfile = async () => { const user=await api.put('/profile',profile); auth.user=user; localStorage.setItem('campus_user',JSON.stringify(user)); editing.value=false; ElMessage.success('资料已保存') }
const offShelf = async (item) => { await ElMessageBox.confirm(`确认下架「${item.title}」吗？`,'下架商品'); await api.delete(`/products/${item.id}`); ElMessage.success('已下架'); load() }
const readAll = async () => { await api.patch('/notifications/read-all'); notifications.value.forEach(i=>i.is_read=true); ElMessage.success('已全部标为已读') }
onMounted(load)
</script>

<template>
  <div class="page-container profile-page">
    <section class="profile-hero surface"><div class="profile-avatar">{{auth.user?.nickname?.slice(0,1)}}</div><div class="profile-main"><div><h1>{{auth.user?.nickname}}</h1><span v-if="auth.user?.verified"><el-icon><CircleCheckFilled /></el-icon> 同济大学认证学生</span></div><p>{{auth.user?.bio||'这个同学很低调，还没有填写个人简介。'}}</p><div class="profile-meta"><span><el-icon><School /></el-icon>{{auth.user?.campus}}</span><span><el-icon><Postcard /></el-icon>{{auth.user?.student_no||'未填写学号'}}</span><span><el-icon><Medal /></el-icon>信用分 {{auth.user?.credit_score}}</span></div></div><button class="secondary-btn" @click="editing=true"><el-icon><Edit /></el-icon> 编辑资料</button><div class="profile-stats"><div><strong>{{productStats.published}}</strong><span>在售</span></div><div><strong>{{productStats.sold}}</strong><span>已售</span></div><div><strong>5.0</strong><span>好评</span></div></div></section>
    <div class="profile-layout">
      <aside class="profile-menu surface"><button v-for="item in [{v:'products',l:'我的发布',i:'Goods'},{v:'notifications',l:'通知中心',i:'Bell'},{v:'credit',l:'信用与认证',i:'Medal'},{v:'security',l:'账号安全',i:'Lock'}]" :key="item.v" :class="{active:active===item.v}" @click="active=item.v"><el-icon><component :is="item.i" /></el-icon>{{item.l}}<span v-if="item.v==='notifications'&&notifications.filter(n=>!n.is_read).length">{{notifications.filter(n=>!n.is_read).length}}</span></button><router-link to="/favorites"><el-icon><Star /></el-icon>我的收藏</router-link><router-link to="/orders"><el-icon><Tickets /></el-icon>我的订单</router-link></aside>
      <main class="profile-content surface surface-padded">
        <template v-if="active==='products'"><div class="content-title"><div><h2>我的发布</h2><p>共发布 {{productStats.total}} 件商品</p></div><router-link to="/publish" class="primary-btn"><el-icon><Plus /></el-icon>发布闲置</router-link></div><div class="my-product-list"><article v-for="item in products" :key="item.id"><img :src="item.images[0]" /><div><router-link :to="`/product/${item.id}`">{{item.title}}</router-link><p>{{item.condition}} · {{item.pickup_location}}</p><span>{{dateTime(item.created_at)}} 发布 · {{item.view_count}} 次浏览 · {{item.favorite_count}} 人收藏</span></div><strong>{{currency(item.price)}}</strong><el-tag :type="statusMap[item.status]?.[1]">{{statusMap[item.status]?.[0]}}</el-tag><div class="product-actions"><router-link :to="`/publish/${item.id}`">编辑</router-link><button v-if="item.status==='published'" @click="offShelf(item)">下架</button></div></article><el-empty v-if="!products.length" description="还没有发布过闲置" /></div></template>
        <template v-else-if="active==='notifications'"><div class="content-title"><div><h2>通知中心</h2><p>订单、审核和平台动态</p></div><button class="text-btn" @click="readAll">全部已读</button></div><div class="profile-notifications"><article v-for="item in notifications" :key="item.id" :class="{unread:!item.is_read}"><span><el-icon><Bell /></el-icon></span><div><strong>{{item.title}}</strong><p>{{item.content}}</p><time>{{dateTime(item.created_at)}}</time></div></article></div></template>
        <template v-else-if="active==='credit'"><div class="content-title"><div><h2>信用与认证</h2><p>真实身份和良好记录，让交易更值得信任</p></div></div><div class="credit-score"><div><strong>{{auth.user?.credit_score}}</strong><span>信用优秀</span></div><ul><li><el-icon><CircleCheckFilled /></el-icon><span><b>校园身份认证</b><small>已认证 {{auth.user?.campus}} 学生身份</small></span></li><li><el-icon><CircleCheckFilled /></el-icon><span><b>手机号认证</b><small>{{auth.user?.phone||'待完善'}}</small></span></li><li><el-icon><CircleCheckFilled /></el-icon><span><b>交易行为良好</b><small>近 90 天无违规、爽约或争议记录</small></span></li></ul></div></template>
        <template v-else><div class="content-title"><div><h2>账号安全</h2><p>管理登录方式和隐私设置</p></div></div><el-descriptions :column="1" border><el-descriptions-item label="登录账号">{{auth.user?.username}}</el-descriptions-item><el-descriptions-item label="绑定邮箱">{{auth.user?.email}}</el-descriptions-item><el-descriptions-item label="绑定手机">{{auth.user?.phone||'未绑定'}}</el-descriptions-item><el-descriptions-item label="登录密码">已设置 <el-button link type="success">修改密码</el-button></el-descriptions-item></el-descriptions></template>
      </main>
    </div>
    <el-dialog v-model="editing" title="编辑个人资料" width="520px"><el-form label-position="top"><el-form-item label="昵称"><el-input v-model="profile.nickname" /></el-form-item><el-form-item label="个人简介"><el-input v-model="profile.bio" type="textarea" :rows="3" /></el-form-item><div class="edit-grid"><el-form-item label="学校"><el-input v-model="profile.campus" /></el-form-item><el-form-item label="学号"><el-input v-model="profile.student_no" /></el-form-item></div><el-form-item label="手机号"><el-input v-model="profile.phone" /></el-form-item></el-form><template #footer><el-button @click="editing=false">取消</el-button><el-button type="success" @click="saveProfile">保存</el-button></template></el-dialog>
  </div>
</template>

<style scoped>
.profile-hero { position:relative; display:flex; align-items:center; gap:20px; min-height:190px; padding:26px 30px; background:#f4f8f1; }.profile-avatar { width:86px; height:86px; display:grid; place-items:center; border:5px solid #fff; border-radius:50%; background:#d9e9d5; color:#174d2d; font-size:34px; font-weight:800; box-shadow:0 6px 18px rgba(26,67,37,.12); }.profile-main { align-self:center; flex:1; }.profile-main>div { display:flex; align-items:center; gap:12px; }.profile-main h1 { color:#153f28; font-size:26px; }.profile-main>div span { display:flex; align-items:center; gap:4px; padding:4px 8px; border-radius:5px; background:#dcefd9; color:#2d7940; font-size:11px; }.profile-main>p { margin-top:9px; color:#647068; }.profile-meta { display:flex; gap:18px; margin-top:16px; color:#6e7971; font-size:12px; }.profile-meta span { display:flex; align-items:center; gap:5px; }.profile-stats { position:absolute; right:28px; bottom:21px; display:flex; gap:0; }.profile-stats div { min-width:70px; text-align:center; }.profile-stats div+div { border-left:1px solid #ccd8cd; }.profile-stats strong,.profile-stats span { display:block; }.profile-stats strong { color:#1d6334; font-size:20px; }.profile-stats span { color:#8b958e; font-size:10px; }.profile-hero>.secondary-btn { align-self:flex-start; }.profile-layout { display:grid; grid-template-columns:210px 1fr; gap:20px; margin-top:20px; align-items:start; }.profile-menu { overflow:hidden; padding:10px; }.profile-menu button,.profile-menu a { width:100%; height:45px; display:flex; align-items:center; gap:10px; padding:0 12px; border:0; border-radius:7px; background:transparent; color:#5d6960; font-size:14px; }.profile-menu button.active { background:#eaf3e7; color:#26763c; font-weight:700; }.profile-menu span { min-width:18px; height:18px; display:grid; place-items:center; margin-left:auto; border-radius:9px; background:#e74c43; color:#fff; font-size:10px; }.profile-content { min-height:540px; }.content-title { display:flex; justify-content:space-between; align-items:center; padding-bottom:17px; border-bottom:1px solid #e2e7e1; }.content-title h2 { color:#173e28; font-size:20px; }.content-title p { margin-top:5px; color:#8a938c; font-size:12px; }.my-product-list article { display:grid; grid-template-columns:90px 1fr 100px 80px 100px; align-items:center; gap:14px; padding:17px 0; border-bottom:1px solid #e8ece7; }.my-product-list img { width:90px; height:75px; object-fit:cover; border-radius:7px; }.my-product-list a { font-weight:700; }.my-product-list p,.my-product-list span { margin-top:6px; color:#8a938c; font-size:11px; }.my-product-list>article>strong { color:#e3572d; font-size:18px; }.product-actions { display:flex; gap:10px; justify-content:flex-end; }.product-actions a,.product-actions button { border:0; background:transparent; color:#27773c; font-size:12px; }.profile-notifications article { display:flex; gap:12px; padding:17px 5px; border-bottom:1px solid #e7ebe6; }.profile-notifications article>span { width:38px; height:38px; display:grid; place-items:center; border-radius:10px; background:#eff3ed; color:#66816a; }.profile-notifications article.unread>span { background:#dfefdc; color:#26743b; }.profile-notifications strong { color:#334039; }.profile-notifications p { margin-top:5px; color:#717b73; font-size:13px; }.profile-notifications time { display:block; margin-top:7px; color:#a2a9a4; font-size:10px; }.credit-score { display:grid; grid-template-columns:230px 1fr; gap:40px; padding:35px 15px; }.credit-score>div { display:grid; place-content:center; height:190px; border-radius:50%; background:#edf5e9; text-align:center; }.credit-score>div strong { color:#23743a; font-size:56px; }.credit-score>div span { color:#5f7163; }.credit-score ul { list-style:none; padding:0; }.credit-score li { display:flex; gap:11px; padding:14px 0; border-bottom:1px solid #e4e8e3; color:#2f7d42; }.credit-score li span { display:block; }.credit-score b,.credit-score small { display:block; }.credit-score b { color:#344139; }.credit-score small { margin-top:4px; color:#8c958e; }.edit-grid { display:grid; grid-template-columns:1fr 1fr; gap:14px; }
</style>
